def plan_contact_lookup_query(contact_name: str, phone_number: str, relationship: str, requested_field: str) -> dict:
    search_contacts_kwargs = {}
    should_call_search_contacts = False
    abstain_reason = ''

    if not requested_field:
        abstain_reason = 'requested_field is blank'
    else:
        if contact_name:
            search_contacts_kwargs['name'] = contact_name.strip()
            should_call_search_contacts = True
        if phone_number:
            search_contacts_kwargs['phone_number'] = phone_number.strip()
            should_call_search_contacts = True
        if relationship:
            search_contacts_kwargs['relationship'] = relationship.strip()
            should_call_search_contacts = True

        if not search_contacts_kwargs:
            abstain_reason = 'missing_lookup_constraint'

    return {
        'should_call_search_contacts': should_call_search_contacts,
        'search_contacts_kwargs': search_contacts_kwargs,
        'answer_field': requested_field,
        'abstain_reason': abstain_reason
    }

def plan_contact_search_from_scalar_constraint(constraint_field: str, constraint_value: str) -> dict:
    normalized_constraint_value = constraint_value.strip()
    if constraint_field == 'phone_number':
        normalized_constraint_value = normalized_constraint_value.replace(' ', '').replace('-', '').replace('(', '').replace(')', '')
        if normalized_constraint_value.startswith('+'):
            return_value = normalized_constraint_value
        else:
            if len(normalized_constraint_value) == 11 and normalized_constraint_value[0] == '1':
                return_value = '+' + normalized_constraint_value
            elif len(normalized_constraint_value) == 10:
                return_value = '+1' + normalized_constraint_value
            else:
                return_value = '+' + normalized_constraint_value
        return {
            'should_call_search': True,
            'search_tool_name': 'search_contacts',
            'search_kwargs': {'phone_number': return_value},
            'normalized_constraint_field': 'phone_number',
            'normalized_constraint_value': return_value,
            'abstain_reason': ''
        }
    elif constraint_field == 'name' or constraint_field == 'relationship':
        return {
            'should_call_search': True,
            'search_tool_name': 'search_contacts',
            'search_kwargs': {constraint_field: normalized_constraint_value},
            'normalized_constraint_field': constraint_field,
            'normalized_constraint_value': normalized_constraint_value,
            'abstain_reason': ''
        }
    else:
        return {
            'should_call_search': False,
            'search_tool_name': '',
            'search_kwargs': {},
            'normalized_constraint_field': '',
            'normalized_constraint_value': '',
            'abstain_reason': 'missing_contact_constraint'
        }

def resolve_search_window_or_bounds(
    current_timestamp: float,
    phrase: str,
    target_domain: str,
    timestamp_intent: str,
    direction: str,
    content_keyword: str = "",
    lookback_days: int = 0,
    timezone_offset: float = 0.0,
) -> dict:
    min_timestamp = 315529200.0
    now = float(current_timestamp)
    if now <= 0:
        return {
            "target_tool_name": "",
            "search_kwargs": {},
            "should_call_search": False,
            "abstain_reason": "missing_current_timestamp",
            "interpretation": "",
            "bounds_source": "abstain",
        }
    domain = str(target_domain or "").strip().lower()
    if domain == "message":
        tool_name = "search_messages"
    elif domain == "reminder":
        tool_name = "search_reminder"
    else:
        return {
            "target_tool_name": "",
            "search_kwargs": {},
            "should_call_search": False,
            "abstain_reason": "unsupported_target_domain",
            "interpretation": "",
            "bounds_source": "abstain",
        }
    intent = str(timestamp_intent or "").strip().lower()
    if domain == "message":
        lower_key = "creation_timestamp_lowerbound"
        upper_key = "creation_timestamp_upperbound"
    elif intent == "creation":
        lower_key = "creation_timestamp_lowerbound"
        upper_key = "creation_timestamp_upperbound"
    elif intent == "reminder":
        lower_key = "reminder_timestamp_lowerbound"
        upper_key = "reminder_timestamp_upperbound"
    else:
        return {
            "target_tool_name": "",
            "search_kwargs": {},
            "should_call_search": False,
            "abstain_reason": "unsupported_timestamp_intent",
            "interpretation": "",
            "bounds_source": "abstain",
        }
    normalized_direction = str(direction or "").strip().lower()
    normalized_phrase = str(phrase or "").strip().lower()
    if not normalized_direction:
        if normalized_phrase in ("yesterday", "today", "later today", "later_today", "upcoming", "recent", "latest", "oldest"):
            normalized_direction = normalized_phrase.replace(" ", "_")
        else:
            return {
                "target_tool_name": "",
                "search_kwargs": {},
                "should_call_search": False,
                "abstain_reason": "ambiguous_phrase",
                "interpretation": "",
                "bounds_source": "abstain",
            }
    offset_seconds = float(timezone_offset) * 3600.0
    local_now = now + offset_seconds
    local_day_start = float(int(local_now // 86400.0) * 86400.0)
    day_start = local_day_start - offset_seconds
    next_day_start = day_start + 86400.0
    kwargs = {}
    interpretation = normalized_direction
    bounds_source = "resolved_direction"
    if normalized_direction == "yesterday":
        kwargs[lower_key] = max(min_timestamp, day_start - 86400.0)
        kwargs[upper_key] = max(min_timestamp, day_start - 1.0)
    elif normalized_direction == "today":
        kwargs[lower_key] = max(min_timestamp, day_start)
        kwargs[upper_key] = max(min_timestamp, next_day_start - 1.0)
    elif normalized_direction == "later_today":
        kwargs[lower_key] = max(min_timestamp, now)
        kwargs[upper_key] = max(min_timestamp, next_day_start - 1.0)
    elif normalized_direction == "upcoming":
        kwargs[lower_key] = max(min_timestamp, now)
    elif normalized_direction == "recent":
        days = int(lookback_days)
        if days <= 0:
            days = 7
        kwargs[lower_key] = max(min_timestamp, now - days * 86400.0)
        kwargs[upper_key] = max(min_timestamp, now)
    elif normalized_direction in ("latest", "oldest"):
        if domain == "message":
            kwargs[upper_key] = max(min_timestamp, now)
        else:
            days = int(lookback_days)
            if days <= 0:
                days = 3650
            kwargs[lower_key] = max(min_timestamp, now - days * 86400.0)
            kwargs[upper_key] = max(min_timestamp, now)
    elif normalized_direction == "custom":
        days = int(lookback_days)
        if days <= 0:
            return {
                "target_tool_name": "",
                "search_kwargs": {},
                "should_call_search": False,
                "abstain_reason": "custom_window_requires_positive_lookback_days",
                "interpretation": "",
                "bounds_source": "abstain",
            }
        kwargs[lower_key] = max(min_timestamp, now - days * 86400.0)
        kwargs[upper_key] = max(min_timestamp, now)
        interpretation = "custom_lookback"
    else:
        return {
            "target_tool_name": "",
            "search_kwargs": {},
            "should_call_search": False,
            "abstain_reason": "unsupported_direction",
            "interpretation": "",
            "bounds_source": "abstain",
        }
    if str(content_keyword or "").strip():
        kwargs["content"] = str(content_keyword)
    if not kwargs:
        return {
            "target_tool_name": "",
            "search_kwargs": {},
            "should_call_search": False,
            "abstain_reason": "no_search_criteria_prepared",
            "interpretation": "",
            "bounds_source": "abstain",
        }
    return {
        "target_tool_name": tool_name,
        "search_kwargs": kwargs,
        "should_call_search": True,
        "abstain_reason": "",
        "interpretation": interpretation,
        "bounds_source": bounds_source,
    }

def select_message_content_by_recency(records: list, selection_mode: str) -> dict:
    """Select the latest/oldest visible message and return answer-ready content."""
    mode = str(selection_mode or "").strip().lower()

    def empty(reason: str, selected_record=None, selected_timestamp=0.0, tie_candidates=None) -> dict:
        return {
            "selected_record": selected_record if isinstance(selected_record, dict) else {},
            "selected_message": selected_record if isinstance(selected_record, dict) else {},
            "selected_message_id": "",
            "selected_content": "",
            "selected_timestamp": float(selected_timestamp or 0.0),
            "should_answer": False,
            "abstain_reason": str(reason or "insufficient_information"),
            "tie_candidates": tie_candidates if isinstance(tie_candidates, list) else [],
            "selection_reason": "",
            "exact_final_answer": "",
            "final_answer_recommendation": "abstain:" + str(reason or "insufficient_information"),
            "copy_exactly": False,
        }

    if not mode:
        return empty("missing_selection_mode")
    if mode not in ("latest", "oldest"):
        return empty("invalid_selection_mode")
    if not isinstance(records, list) or not records:
        return empty("no_records")

    candidates = []
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            continue
        raw_ts = record.get("creation_timestamp")
        if isinstance(raw_ts, bool) or not isinstance(raw_ts, (int, float)):
            continue
        candidates.append((index, record, float(raw_ts)))
    if not candidates:
        return empty("no_numeric_creation_timestamps")

    target_ts = max(item[2] for item in candidates) if mode == "latest" else min(item[2] for item in candidates)
    tied = [(index, record, ts) for index, record, ts in candidates if ts == target_ts]
    if len(tied) != 1:
        return empty("ambiguous_timestamp_tie", selected_timestamp=target_ts, tie_candidates=[record for _, record, _ in tied])

    selected_index, selected, selected_ts = tied[0]
    content = str(selected.get("content") or "").strip()
    if not content:
        return empty("selected_message_missing_content", selected, selected_ts)
    message_id = selected.get("message_id")
    label = "most recent" if mode == "latest" else "oldest"
    exact_final_answer = "Your %s message says '%s'." % (label, content)
    return {
        "selected_record": selected,
        "selected_message": selected,
        "selected_message_id": "" if message_id in (None, "") else str(message_id),
        "selected_content": content,
        "selected_timestamp": float(selected_ts),
        "should_answer": True,
        "abstain_reason": "",
        "tie_candidates": [],
        "selection_reason": "selected_%s_message_by_creation_timestamp_at_index_%s" % (mode, selected_index),
        "exact_final_answer": exact_final_answer,
        "final_answer_recommendation": exact_final_answer,
        "copy_exactly": True,
    }

def select_message_counterparty_for_contact_update(records: list, selection_mode: str, updates: dict = None, self_person_id: str = "") -> dict:
    """Select a message counterparty for contact updates without emitting unsafe ids."""
    updates = updates if isinstance(updates, dict) else {}
    self_person_id = str(self_person_id or "").strip()

    def _text(value) -> str:
        return "" if value in (None, "") else str(value).strip()

    def _uuid_like(value) -> bool:
        text = _text(value)
        if len(text) != 36:
            return False
        if [text[8], text[13], text[18], text[23]] != ["-", "-", "-", "-"]:
            return False
        return all(ch in "0123456789abcdefABCDEF" for ch in text.replace("-", ""))

    def _phone_like(value) -> bool:
        text = _text(value)
        return text.startswith("+") and text[1:].isdigit() and len(text) >= 8

    def empty(reason: str, selected_record=None, selected_timestamp=0.0, tie_candidates=None) -> dict:
        return {
            "selected_record": selected_record if isinstance(selected_record, dict) else {},
            "selected_message": selected_record if isinstance(selected_record, dict) else {},
            "selected_message_id": "",
            "selected_person_id": "",
            "selected_phone_number": "",
            "selected_timestamp": float(selected_timestamp or 0.0),
            "downstream_tool_name": "",
            "downstream_tool_kwargs": {},
            "should_call_tool": False,
            "tie_candidates": tie_candidates if isinstance(tie_candidates, list) else [],
            "abstain_reason": str(reason or ""),
            "safety_notes": "abstain; no unique safe contact update target",
            "final_answer_recommendation": "abstain:" + str(reason or "insufficient_information"),
        }

    if not isinstance(records, list) or not records:
        return empty("no_records")
    mode = str(selection_mode or "").strip().lower()
    if mode not in ("latest", "oldest"):
        return empty("invalid_selection_mode")

    candidates = []
    id_counts = {}
    phone_counts = {}
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            continue
        for key in ("sender_person_id", "recipient_person_id"):
            value = _text(record.get(key))
            if _uuid_like(value):
                id_counts[value] = id_counts.get(value, 0) + 1
        for key in ("sender_phone_number", "recipient_phone_number"):
            value = _text(record.get(key))
            if _phone_like(value):
                phone_counts[value] = phone_counts.get(value, 0) + 1
        raw_ts = record.get("creation_timestamp")
        if isinstance(raw_ts, bool) or not isinstance(raw_ts, (int, float)):
            continue
        candidates.append((index, record, float(raw_ts)))
    if not candidates:
        return empty("no_numeric_creation_timestamps")

    target_ts = max(item[2] for item in candidates) if mode == "latest" else min(item[2] for item in candidates)
    tied = [(idx, msg, ts) for idx, msg, ts in candidates if ts == target_ts]
    if len(tied) != 1:
        return empty("ambiguous_timestamp_tie", selected_timestamp=target_ts, tie_candidates=[msg for _, msg, _ in tied])

    _idx, selected, selected_ts = tied[0]
    sender_id = _text(selected.get("sender_person_id"))
    recipient_id = _text(selected.get("recipient_person_id"))
    sender_phone = _text(selected.get("sender_phone_number"))
    recipient_phone = _text(selected.get("recipient_phone_number"))

    sides = [
        {
            "role": "sender",
            "person_id": sender_id if _uuid_like(sender_id) else "",
            "raw_person_id": sender_id,
            "phone_number": sender_phone if _phone_like(sender_phone) else "",
        },
        {
            "role": "recipient",
            "person_id": recipient_id if _uuid_like(recipient_id) else "",
            "raw_person_id": recipient_id,
            "phone_number": recipient_phone if _phone_like(recipient_phone) else "",
        },
    ]

    if self_person_id and _uuid_like(self_person_id):
        if sender_id == self_person_id:
            selected_side = sides[1]
        elif recipient_id == self_person_id:
            selected_side = sides[0]
        else:
            selected_side = None
    else:
        usable = [
            side for side in sides
            if side["person_id"] or side["phone_number"]
        ]
        if not usable:
            return empty("missing_counterparty_identity", selected, selected_ts)

        def side_rank(side):
            phone = side["phone_number"]
            person_id = side["person_id"]
            phone_count = phone_counts.get(phone, 9999) if phone else 9999
            id_count = id_counts.get(person_id, 9999) if person_id else 9999
            # Prefer the less frequent phone/identity in the visible messages.
            # The more frequent side is usually the user's own endpoint.
            return (
                phone_count,
                id_count,
                0 if person_id else 1,
                0 if phone else 1,
                side["role"],
            )

        ranked = sorted(usable, key=side_rank)
        if len(ranked) > 1 and side_rank(ranked[0])[:4] == side_rank(ranked[1])[:4]:
            return empty("ambiguous_counterparty_without_self_id", selected, selected_ts)
        selected_side = ranked[0]

    if selected_side is None:
        return empty("self_id_not_present_in_selected_message", selected, selected_ts)

    person_id = selected_side["person_id"]
    phone_number = selected_side["phone_number"]
    if not person_id and not phone_number:
        return empty("selected_counterparty_has_no_safe_identifier", selected, selected_ts)

    message_id = selected.get("message_id")
    has_update = any(
        value is not None and (not isinstance(value, str) or value.strip())
        for value in updates.values()
    )
    if person_id:
        downstream_tool_name = "modify_contact"
        downstream_tool_kwargs = {"person_id": person_id, **updates} if has_update else {}
        should_call_tool = bool(has_update)
        recommendation = "call:modify_contact" if has_update else "use_selected_record:missing_update_fields"
        safety = (
            "safe contact id selected; call modify_contact with selected_person_id "
            "after collecting requested update fields"
        )
    else:
        downstream_tool_name = "search_contacts"
        downstream_tool_kwargs = {"phone_number": phone_number}
        should_call_tool = True
        recommendation = "call:search_contacts_then_modify_contact"
        safety = (
            "no reliable person_id in message record; search_contacts by selected_phone_number "
            "before any modify_contact call"
        )

    return {
        "selected_record": selected,
        "selected_message": selected,
        "selected_message_id": "" if message_id in (None, "") else str(message_id),
        "selected_person_id": person_id,
        "selected_phone_number": phone_number,
        "selected_timestamp": float(selected_ts),
        "downstream_tool_name": downstream_tool_name,
        "downstream_tool_kwargs": downstream_tool_kwargs,
        "should_call_tool": should_call_tool,
        "tie_candidates": [],
        "abstain_reason": "",
        "safety_notes": safety,
        "final_answer_recommendation": recommendation,
    }

def select_record_by_timestamp_extreme(
    records,
    timestamp_field,
    mode,
    tie_break_fields=None,
    required_filters=None,
    allow_missing_timestamp=False,
):
    if mode not in ("latest", "oldest"):
        return {
            "selected_record": None,
            "selected_index": None,
            "selected_timestamp": None,
            "should_use_selected_record": False,
            "abstain_reason": "invalid_mode",
            "selection_reason": "",
        }
    best_idx = None
    best_record = None
    best_ts = None
    for i, record in enumerate(records or []):
        if not isinstance(record, dict):
            continue
        if required_filters:
            filter_match = True
            for _fk, _fv in required_filters.items():
                if record.get(_fk) != _fv:
                    filter_match = False
                    break
            if not filter_match:
                continue
        ts_raw = record.get(timestamp_field)
        if ts_raw is None:
            continue
        if not isinstance(ts_raw, (int, float)):
            continue
        ts_val = float(ts_raw)
        if best_ts is None:
            best_idx = i
            best_record = record
            best_ts = ts_val
        elif mode == "latest" and ts_val > best_ts:
            best_idx = i
            best_record = record
            best_ts = ts_val
        elif mode == "oldest" and ts_val < best_ts:
            best_idx = i
            best_record = record
            best_ts = ts_val
    if best_record is None:
        return {
            "selected_record": None,
            "selected_index": None,
            "selected_timestamp": None,
            "should_use_selected_record": False,
            "abstain_reason": "no_valid_timestamped_records",
            "selection_reason": "",
        }
    return {
        "selected_record": best_record,
        "selected_index": best_idx,
        "selected_timestamp": best_ts,
        "should_use_selected_record": True,
        "abstain_reason": "",
        "selection_reason": "selected_" + mode + "_by_" + str(timestamp_field),
    }
